window.__posterData({"id": "sevda-nowbakht", "name": "Sevda Nowbakht", "folder": "weak1 poster_sevda_nowbakht_AI", "v": "1", "scripts": ["https://cdn.jsdelivr.net/npm/p5@1.11.11/lib/p5.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// ---------- Konstanter ----------\nconst CANVAS_W = 500;\nconst CANVAS_H = 800;\nconst CENTER_X = CANVAS_W / 2;\nconst RING_CENTER_Y = 400;\nconst ROTATION_SPEED = 0.05;\n// Discokulans mittpunkt (strålarna utgår härifrån)\nconst BALL_X = 250;\nconst BALL_Y = 50;\n\n// Neonringar: [färg, tjocklek, diameter, startvinkel, slutvinkel]\nconst ARCS = [\n  [\"#A855F7\", 5, 300, 0, Math.PI],\n  [\"#00FFFF\", 4, 400, Math.PI, Math.PI * 2],\n  [\"#FF00FF\", 4, 460, 0, Math.PI / 2],\n  [\"#f5ec00\", 4, 490, 0.2, 0.7],\n  [\"#00f900\", 4, 380, Math.PI, Math.PI + Math.PI / 4],\n  [\"#fffb00\", 4, 360, Math.PI / 2, Math.PI],\n  [\"#00f900\", 4, 500, Math.PI + Math.PI / 4, Math.PI * 2],\n  [\"#ff40ff\", 4, 350, Math.PI + Math.PI / 4, Math.PI * 2],\n  [\"#00f900\", 4, 470, Math.PI / 2, Math.PI],\n  [\"#ff40ff\", 4, 480, Math.PI, Math.PI + Math.PI / 4],\n  [\"#00f900\", 4, 320, 0, Math.PI / 2],\n];\n\n// ---------- Tillstånd ----------\nlet angle = 0;        // Rotationsvinkel för cirklarna\nlet spinning = false; // Cirklarna står stilla från början\nlet bounce = 0;       // Styr textens rörelse\nlet discoBild;\n\nfunction preload() {\n  discoBild = loadImage(\"discoball.png\");\n}\n\nfunction setup() {\n  createCanvas(CANVAS_W, CANVAS_H); // Skapar affischens storlek\n}\n\nfunction draw() {\n  background(spinning ? \"black\" : \"white\");\n\n  // Texten rör sig bara när animationen är igång\n  bounce = spinning ? sin(frameCount * 0.1) * 10 : 0;\ndrawBeams(); // NY\n  drawDiscoBall();\n  drawTitle();\n  drawName();\n  drawRings();\n\n  // Cirklarna roterar bara när spinning är true\n  if (spinning) {\n    angle += ROTATION_SPEED;\n  }\n}\n\n// Visar discokulan ovanför texten\nfunction drawDiscoBall() {\n  image(discoBild, 205, 5, 90, 90);\n}\n\n// AI ändring av texten \n// Textens placering och utseende, med neonglöd när spinning är true\nfunction drawTitle() {\n  textFont(\"impact\");\n  textAlign(CENTER);\n  noStroke();\n  textSize(45);\n\n  // Glödens styrka pulserar när animationen är igång\n  const glow = spinning ? 25 + sin(frameCount * 0.1) * 10 : 0;\n\n  glowText(\"MIDNIGHT\", CENTER_X, 400 + bounce, spinning ? \"white\" : \"black\", \"#00FFFF\", glow);\n  glowText(\"RAVE\", CENTER_X, 460 + bounce, \"#FF00FF\", \"#FF00FF\", glow);\n\n  noFill();\n}\n\n// Ritar text med glöd. Ritas två gånger så att glöden blir starkare.\nfunction glowText(str, x, y, textColor, glowColor, blur) {\n  fill(textColor);\n  drawingContext.shadowColor = glowColor;\n  drawingContext.shadowBlur = blur;\n\n  text(str, x, y);\n  if (blur > 0) text(str, x, y);\n\n  drawingContext.shadowBlur = 0; // Stänger av glöden så inget annat påverkas\n}\n\n// Mitt namn längst ner på affischen\nfunction drawName() {\n  fill(\"white\");\n  noStroke();\n  textAlign(CENTER);\n  textSize(16);\n  text(\"Sevda Nowbakht\", CENTER_X, 750);\n  noFill(); // Tar bort fyllningen från cirklarna\n}\n\n// Färgade cirkelbågar runt texten\nfunction drawRings() {\n  push();\n  translate(CENTER_X, RING_CENTER_Y); // Flyttar rotationspunkten till mitten\n  rotate(angle);\n  noFill();\n\n  // Fem extra neonringar\n  stroke(\"#FF00FF\");\n  strokeWeight(1);\n  for (let i = 0; i < 5; i++) {\n    const d = 280 + i * 40;\n    arc(0, 0, d, d, 0, PI);\n  }\n\n  // Övriga färgade bågar\n  for (const [col, weight, diameter, start, stop] of ARCS) {\n    stroke(col);\n    strokeWeight(weight);\n    arc(0, 0, diameter, diameter, start, stop);\n  }\n\n  pop(); // Återställer koordinatsystemet\n}\n\n// Startar och stoppar rotationen vid musklick\nfunction mousePressed() {\n  spinning = !spinning;\n}\n\n\n\n// Neonljusstrålar som svepar ut från discokulan (bara när spinning är true)\nconst BEAM_COUNT = 4;\nconst BEAM_COLORS = [\"#FF00FF\", \"#00FFFF\", \"#00f900\", \"#f5ec00\"];\n\nfunction drawBeams() {\n  if (!spinning) return;\n\n  noStroke();\n  for (let i = 0; i < BEAM_COUNT; i++) {\n    // Varje stråle svänger i sin egen takt\n    const sway = sin(frameCount * 0.03 + i * 1.5) * 0.5;\n    const dir = HALF_PI + (i - (BEAM_COUNT - 1) / 2) * 0.45 + sway;\n    const spread = 0.07; // Strålens bredd\n    const len = 900;     // Strålens längd\n\n    const c = color(BEAM_COLORS[i % BEAM_COLORS.length]);\n    c.setAlpha(45);\n    fill(c);\n\n    triangle(\n      BALL_X, BALL_Y,\n      BALL_X + cos(dir - spread) * len, BALL_Y + sin(dir - spread) * len,\n      BALL_X + cos(dir + spread) * len, BALL_Y + sin(dir + spread) * len\n    );\n  }\n  noFill();\n}\n\n\n//1. kan du översätt, kodens längd är uenför samma med jag känner att det är mer orginsterat\n\n//2.jag ändrade så att texetn lyser med neon färg när muse är pressed och den svara bakgruden vissas \n\n//3. AI gjorde så att diskokualn har strålkastare när muse är present, villket jag tycker passade bra in i min rave poster efter som det gav en rave känsla och disokulan nu fyller mer av en funktion ", "assets": {"discoball.png": {"mime": "image/webp", "b64": ""}}});
